OEE.filter:
var TZ_OFFSET_MIN = 330;

// Current time
var now = new Date().getTime();

// Convert to IST
var localMs = now + TZ_OFFSET_MIN * 60000;
var localMidnight = localMs - (localMs % 86400000);
var hour = (localMs - localMidnight) / 3600000;

// Determine shift
var shiftHour;
if (hour < 8) {
    shiftHour = 0;
} else if (hour < 16) {
    shiftHour = 8;
} else {
    shiftHour = 16;
}

// Current shift start in UTC timestamp
var currentShiftStart = localMidnight + shiftHour * 3600000 - TZ_OFFSET_MIN * 60000;

// Filter
return shift_start == currentShiftStart;

